#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1000000007LL;

long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    a %= MOD;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<string> g(n);
    for (int i = 0; i < n; i++) cin >> g[i];
    long long N = 1LL * n * m;

    vector<int> comp(n * m, -1);
    auto id = [&](int x, int y) { return x * m + y; };
    const int dx[4] = {1, -1, 0, 0};
    const int dy[4] = {0, 0, 1, -1};

    int cid = 0;
    queue<pair<int, int>> q;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (g[i][j] == 'R' && comp[id(i, j)] == -1) {
                comp[id(i, j)] = cid;
                q.push({i, j});
                while (!q.empty()) {
                    auto [x, y] = q.front(); q.pop();
                    for (int k = 0; k < 4; k++) {
                        int nx = x + dx[k], ny = y + dy[k];
                        if (0 <= nx && nx < n && 0 <= ny && ny < m && g[nx][ny] == 'R') {
                            int v = id(nx, ny);
                            if (comp[v] == -1) {
                                comp[v] = cid;
                                q.push({nx, ny});
                            }
                        }
                    }
                }
                ++cid;
            }
        }
    }
    long long C0 = cid;

    long long W = 0, sumk = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (g[i][j] == 'W') {
                ++W;
                int uniq[4], cnt = 0;
                auto push = [&](int t) {
                    for (int u = 0; u < cnt; ++u) if (uniq[u] == t) return;
                    uniq[cnt++] = t;
                };
                if (i > 0 && g[i - 1][j] == 'R') push(comp[id(i - 1, j)]);
                if (i + 1 < n && g[i + 1][j] == 'R') push(comp[id(i + 1, j)]);
                if (j > 0 && g[i][j - 1] == 'R') push(comp[id(i, j - 1)]);
                if (j + 1 < m && g[i][j + 1] == 'R') push(comp[id(i, j + 1)]);
                sumk += cnt;
            }
        }
    }

    long long S = ((C0 % MOD) * (N % MOD) + (W - sumk)) % MOD;
    if (S < 0) S += MOD;
    long long invN = modpow(N % MOD, MOD - 2);
    cout << (S * invN) % MOD << "\n";
    return 0;
}
